public class PlaylistQueueEditorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String contents(javax.swing.JList<?> list) {
        StringBuilder sb = new StringBuilder("[");
        javax.swing.ListModel<?> m = list.getModel();
        for (int i = 0; i < m.getSize(); i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(m.getElementAt(i));
        }
        return sb.append("]").toString();
    }

    public static void main(String[] args) {
        try {
            PlaylistQueueEditor panel = new PlaylistQueueEditor();
            java.awt.Component listComp = find(panel, "songs");
            java.awt.Component fieldComp = find(panel, "songField");
            java.awt.Component addComp = find(panel, "addButton");
            check("list and field found", true,
                    listComp instanceof javax.swing.JList && fieldComp instanceof javax.swing.JTextField);
            if (listComp instanceof javax.swing.JList && fieldComp instanceof javax.swing.JTextField
                    && addComp instanceof javax.swing.JButton) {
                javax.swing.JList<?> songs = (javax.swing.JList<?>) listComp;
                javax.swing.JTextField field = (javax.swing.JTextField) fieldComp;
                javax.swing.JButton addButton = (javax.swing.JButton) addComp;
                field.setText("One");
                addButton.doClick();
                field.setText("  Two  ");
                addButton.doClick();
                field.setText("Three");
                addButton.doClick();
                check("three songs added and trimmed", "[One, Two, Three]", contents(songs));
                check("field cleared after adding", "", field.getText());
                check("newest song is selected", 2, songs.getSelectedIndex());
                field.setText("   ");
                addButton.doClick();
                check("blank entry is ignored", 3, songs.getModel().getSize());
                panel.moveSelectedUp();
                check("selected song moved up", "[One, Three, Two]", contents(songs));
                check("selection follows the moved song", 1, songs.getSelectedIndex());
                songs.setSelectedIndex(0);
                panel.moveSelectedUp();
                check("top song cannot move up", "[One, Three, Two]", contents(songs));
                songs.setSelectedIndex(2);
                panel.removeSelected();
                check("last song removed", "[One, Three]", contents(songs));
                check("selection clamped to the new last row", 1, songs.getSelectedIndex());
                panel.removeSelected();
                panel.removeSelected();
                check("selection cleared on an empty list", -1, songs.getSelectedIndex());
                panel.removeSelected();
                check("removing from an empty list is safe", "[]", contents(songs));
            } else {
                failures++;
                System.out.println("FAIL  songs, songField or addButton not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

