import javax.swing.DefaultListModel;
import javax.swing.JButton;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JTextField;

public class PlaylistQueueEditor extends JPanel {

    private final DefaultListModel<String> model = new DefaultListModel<>();
    private final JList<String> songs = new JList<>(model);
    private final JTextField songField = new JTextField(12);
    private final JButton addButton = new JButton("Add");
    private final JButton removeButton = new JButton("Remove");
    private final JButton upButton = new JButton("Up");

    public PlaylistQueueEditor() {
        songs.setName("songs");
        songField.setName("songField");
        addButton.setName("addButton");
        removeButton.setName("removeButton");
        upButton.setName("upButton");
        add(songField);
        add(addButton);
        add(removeButton);
        add(upButton);
        add(songs);
        addButton.addActionListener(e -> addSong());
        removeButton.addActionListener(e -> removeSelected());
        upButton.addActionListener(e -> moveSelectedUp());
    }

    public void addSong() {
        String title = songField.getText().trim();
        if (title.isEmpty()) {
            return;
        }
        model.addElement(title);
        songField.setText("");
        songs.setSelectedIndex(model.getSize() - 1);
    }

    public void removeSelected() {
        int index = songs.getSelectedIndex();
        if (index < 0) {
            return;
        }
        model.remove(index);
        if (model.getSize() == 0) {
            songs.clearSelection();
        } else if (index >= model.getSize()) {
            songs.setSelectedIndex(model.getSize() - 1);
        } else {
            songs.setSelectedIndex(index);
        }
    }

    public void moveSelectedUp() {
        int index = songs.getSelectedIndex();
        if (index <= 0) {
            return;
        }
        String moved = model.remove(index);
        model.add(index - 1, moved);
        songs.setSelectedIndex(index - 1);
    }
}
